import requests
for repo in ['phykit','biopython','python']:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/'
    try:
        r=requests.get(url, params={'limit':20}, timeout=20)
        print('repo', repo, 'status', r.status_code)
        if r.ok:
            tags=[t['name'] for t in r.json().get('tags',[])[:10]]
            print('\\n'.join(tags[:10]))
    except Exception as e:
        print('ERR', repo, type(e).__name__, e)
PY"

